examples.question_text:
The rectangular prism has a volume of $168\text{ cm}^{3}$. Find its missing dimension $x$.
[tikz]
% mathsmap-solid {"version":1,"kind":"polyhedron","model":{"version":1,"kind":"polyhedron","vertices":{"a":[0,0,0],"b":[3,0,0],"c":[3,2,0],"d":[0,2,0],"e":[0,0,2],"f":[3,0,2],"g":[3,2,2],"h":[0,2,2]},"faces":[["a","d","c","b"],["e","f","g","h"],["a","b","f","e"],["b","c","g","f"],["c","d","h","g"],["d","a","e","h"]],"view":{"right":[1,0,0.5],"up":[0,1,0.35],"toward":[0.5,0.35,-1]}}}
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (a) at (0,0);
\coordinate (b) at (3,0);
\coordinate (c) at (3,2);
\coordinate (d) at (0,2);
\coordinate (e) at (1,0.7);
\coordinate (f) at (4,0.7);
\coordinate (g) at (4,2.7);
\coordinate (h) at (1,2.7);
\draw (a)--(b)--(c)--(d)--cycle;
\draw (b)--(f)--(g)--(c);
\draw (d)--(h)--(g);
\draw[dashed] (a)--(e)--(f);
\draw[dashed] (e)--(h);
\path (a)--(b) node[midway,below] {$7\text{ cm}$};
\path (b)--(c) node[midway,left] {$4\text{ cm}$};
\path (b)--(f) node[midway,below right] {$x$};
\end{tikzpicture}
[/tikz]
